  <script>
  (function () {
    var countdown = document.querySelector('.lp-bgi-countdown');
    if (!countdown) return;

    var deadline = new Date(countdown.getAttribute('data-deadline')).getTime();
    var daysEl = countdown.querySelector('[data-countdown-days]');
    var hoursEl = countdown.querySelector('[data-countdown-hours]');
    var minutesEl = countdown.querySelector('[data-countdown-minutes]');
    var secondsEl = countdown.querySelector('[data-countdown-seconds]');

    function pad(value) {
      return String(value).padStart(2, '0');
    }

    function updateCountdown() {
      var remaining = Math.max(0, deadline - Date.now());
      var totalSeconds = Math.floor(remaining / 1000);
      var days = Math.floor(totalSeconds / 86400);
      var hours = Math.floor((totalSeconds % 86400) / 3600);
      var minutes = Math.floor((totalSeconds % 3600) / 60);
      var seconds = totalSeconds % 60;

      daysEl.textContent = String(days);
      hoursEl.textContent = pad(hours);
      minutesEl.textContent = pad(minutes);
      secondsEl.textContent = pad(seconds);
    }

    updateCountdown();
    window.setInterval(updateCountdown, 1000);
  }());

  (function () {
    var section = document.getElementById('ket-qua-dieu-tri');
    if (!section) return;
    var track = section.querySelector('.lp-bgi-carousel-track');
    if (!track) return;
    var wrapper = section.querySelector('.lp-bgi-carousel-wrapper');
    var prev = wrapper.querySelector('.lp-bgi-carousel-prev');
    var next = wrapper.querySelector('.lp-bgi-carousel-next');
    var slides = track.children;
    var idx = 0;

    function getVisible() {
      var w = window.innerWidth;
      if (w <= 600) return 1;
      if (w <= 992) return 2;
      return 3;
    }
    function move(dir) {
      var vis = getVisible();
      var max = slides.length - vis;
      idx = Math.max(0, Math.min(idx + dir, max));
      var slideW = slides[0].offsetWidth + 24;
      track.style.transform = 'translateX(-' + (idx * slideW) + 'px)';
    }
    prev.addEventListener('click', function () { move(-1); });
    next.addEventListener('click', function () { move(1); });
    window.addEventListener('resize', function () { move(0); });
  })();
  </script>

